const token = $env.TELEGRAM_BOT_TOKEN;
const chat = String($env.TELEGRAM_CHAT_ID);
const api = (method, body) => this.helpers.httpRequest({
  method: 'POST', url: `https://api.telegram.org/bot${token}/${method}`, body, json: true, timeout: 10000,
});

let updates;
try {
  updates = await api('getUpdates', { timeout: 0, allowed_updates: ['message', 'callback_query'] });
} catch (e) {
  const msg = String(e.message || e);
  if (/\b(409|429)\b/.test(msg) || /conflict/i.test(msg)) {
    return [{ json: { event: null, note: 'conflict' } }];
  }
  throw e;
}

const events = [];
let lastId = 0;
for (const u of updates.result || []) {
  lastId = Math.max(lastId, u.update_id);
  const cq = u.callback_query;
  if (cq && String(cq.message?.chat?.id) === chat) {
    const m = /^ap:(\d+):([ar])$/.exec(cq.data || '');
    await api('answerCallbackQuery', {
      callback_query_id: cq.id,
      text: m ? (m[2] === 'a' ? 'Одобрено' : 'Отклонено') : '',
    }).catch(() => {});
    if (m) {
      await api('editMessageReplyMarkup', {
        chat_id: chat, message_id: cq.message.message_id, reply_markup: { inline_keyboard: [] },
      }).catch(() => {});
      events.push({ json: { event: { type: 'decision', approval_id: Number(m[1]), decision: m[2] === 'a' ? 'approved' : 'rejected' } } });
    }
  }
  const msg = u.message;
  if (msg && String(msg.chat.id) === chat && msg.reply_to_message && msg.text) {
    await api('editMessageReplyMarkup', {
      chat_id: chat, message_id: msg.reply_to_message.message_id, reply_markup: { inline_keyboard: [] },
    }).catch(() => {});
    events.push({ json: { event: { type: 'reply', message_id: msg.reply_to_message.message_id, text: msg.text } } });
  }
}
if (lastId) {
  await api('getUpdates', { offset: lastId + 1, timeout: 0 }).catch(() => {});
}
return events.length ? events : [{ json: { event: null } }];
